namespace gui_forms {

// ReviewCard's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/review_card.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The review shown: key, title, summary, verdict and disposition. A change rewrites the three labels, the accessible name and description and the visual status, then raises record_changed. An invalid or unbounded record throws std::invalid_argument.
template <typename Declaring>
struct ReviewCardRecordCapability {
    PropertyCell<ReviewRecord, ReviewCardRecordCapability<Declaring>> record{};

    static void assign(ReviewCardRecordCapability& capability, ReviewRecord incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.record), incoming);
        if (!capability.record.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.record));
    }
};

// Every ReviewCard capability, in the order the declaring class takes them.
template <typename Declaring>
struct ReviewCardCapabilities : public ReviewCardRecordCapability<Declaring> {};

} // namespace gui_forms
